#define MAX_PATH_ITEMS 32
static const napi_type_tag profile_tag={UINT64_C(0x821b6482be12475d),UINT64_C(0x959d0efa4083cd77)};
typedef struct {wchar_t *path,*sddl;HANDLE handle;BY_HANDLE_FILE_INFORMATION identity;int optional_birth,allow_write,allow_admin;} HeldPath;
typedef struct {TOKEN_USER *user;HeldPath entries[MAX_PATH_ITEMS];size_t count;HANDLE initialization,unknown;int closed,failed;} ProfileLease;
static napi_value denied(napi_env env){napi_throw_error(env,NULL,"windows_profile_custody_unavailable");return NULL;}
static TOKEN_USER *token_user(void){HANDLE token=NULL;DWORD size=0;TOKEN_USER *result=NULL;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token))return NULL;GetTokenInformation(token,TokenUser,NULL,0,&size);if(size&&size<65536){result=(TOKEN_USER*)calloc(size,1);if(result&&!GetTokenInformation(token,TokenUser,result,size,&size)){free(result);result=NULL;}}if(!CloseHandle(token)){free(result);result=NULL;}return result;}
