 HANDLE current=open_metadata(entry->path,(entry->identity.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)!=0,entry->allow_write);if(current==INVALID_HANDLE_VALUE)goto bad;int matches=snapshot(current,lease->user,&identity,&sddl,0,entry->allow_admin)&&same_object(&entry->identity,&identity)&&wcscmp(entry->sddl,sddl)==0&&canonical_path(current,entry->path);if(sddl)LocalFree(sddl);if(!CloseHandle(current)){lease->unknown=current;goto bad;}if(!matches)goto bad;
