napi_value init_windows_profile_custody(napi_env env,napi_value exports){napi_property_descriptor methods[]={{"holdProfile",NULL,hold_profile,NULL,NULL,NULL,napi_default,NULL},{"publishProfileFile",NULL,publish_profile_file,NULL,NULL,NULL,napi_default,NULL}};if(napi_define_properties(env,exports,2,methods)!=napi_ok)return denied(env);return exports;}
